P=pathlib.Path(__file__).parent;R=P.resolve().parents[6];J=json.load(open(R/'src/data/manufacturing/surface.json'))['lessons'][42:45]
D=[('प्रशिक्षण की सीमा औरKYT के कार्य लक्ष्य जाँचें','प्रशिक्षण,OJT औरKYT की भूमिकाएँ अलग करें।\nखतरे की पहचान को ठोस कार्रवाई से जोड़ें।',[
('काम बदले तो फिर जाँचें','नए उपकरण या सामग्री और बदली कार्यविधि में केवल पुराने अनुभव से कार्य सीमा तय न करें। प्रशिक्षण में खतरे और हानिकारक प्रभाव, सुरक्षा यंत्र औरPPE, कार्यविधि, काम से पहले निरीक्षण, कार्यस्थल व्यवस्था तथा दुर्घटना में सूचना और निकासी आदि जाँचें। अस्पष्ट शब्द या प्रक्रिया के बारे में काम शुरू करने से पहले जिम्मेदार व्यक्ति से पूछें।\nखतरनाक या हानिकारक काम में शर्तों के अनुसार योग्यता, कौशल प्रशिक्षण या विशेष शिक्षा आदि की जाँच जरूरी हो सकती है। केवल नाम से सभी के लिए समान प्रशिक्षण पर्याप्त न मानें। वास्तविक वैधानिक श्रेणी और अधिकार कार्यस्थल के प्रभावी नियंत्रित दस्तावेज और जिम्मेदार व्यक्ति से जाँचें।'),
('OJT में समझाने और दिखाने के बाद जाँच होती है','OJT वास्तविक काम के माध्यम से ज्ञान और कौशल सीखने की विधि है। प्रशिक्षक की व्याख्या और प्रदर्शन के बाद अनुमति प्राप्त सुरक्षित सीमा में काम करें; फिर सुझाव लेकर गलतियाँ सुधारें। एक बार देखना और अकेले जिम्मेदारी लेने की अनुमति अलग बातें हैं।\nप्रशिक्षक दूर जाए तो अपुष्ट संचालन अनुमान से जारी न रखें। पहले काम की सीमा, रोकने की शर्तें और प्रश्न पूछने वाला व्यक्ति तय करें; समझ और कौशल की जाँच रिकॉर्ड करें।'),
('KYT के चार चरणों को कार्रवाई तक पहुँचाएँ','KYT में स्थल के चित्र या स्थिति से असुरक्षित व्यवहार और अवस्थाएँ पहचानते हैं, प्रमुख खतरा चुनते हैं, ठोस उपाय सोचते हैं और टीम के कार्य लक्ष्य बनाते हैं। केवल खतरों की सूची से उपाय का क्रियान्वयन सत्यापित नहीं होता।\n“सावधान रहें” से कौन क्या करेगा स्पष्ट नहीं होता। जिम्मेदार व्यक्ति, स्थिति, कार्रवाई और जाँच विधि स्पष्ट करें। चर्चा और इशारा करके बोलना आवश्यक गार्ड या पृथक्करण जैसे उपकरण उपायों का विकल्प नहीं।'),
('परिवहन रास्ता बदलने पर','नई ट्रॉली से पार्ट ले जाने से पहले चित्र में रास्ते के ऊँच-नीच और चौराहे जाँचें। “चौराहे से पहले रुकें, दोनों ओर देखकर आगे बढ़ें” जैसा कार्य प्रस्ताव बनाएँ। जिम्मेदार व्यक्ति उपकरण और रास्ते के उपाय तथा प्रशिक्षण सीमा जाँचे। खतरा ढूँढ़ने के लिए चलते परिवहन मार्ग में न जाएँ।')],['काम के माध्यम से मार्गदर्शन और सत्यापन वाला प्रशिक्षण।','खतरे का पूर्वानुमान करके उपाय और कार्य लक्ष्य सोचने का प्रशिक्षण।','कौन क्या करेगा स्पष्ट बताने वाला लक्ष्य।','प्रशिक्षण और जाँच में शामिल काम और शर्तों की सीमा।'],'शब्द4मिनट, प्रशिक्षण औरOJT का अंतर8मिनट, KYT के चार चरण8मिनट, परिवहन उदाहरण के कार्य लक्ष्य7मिनट; अंत में3मिनट में अकेले काम की अनुमति की शर्तें जाँचें।',['बिना प्रशिक्षण या अनुमति के उपकरण पर अभ्यास न करें।','KYT चर्चा से सुरक्षा यंत्र हटाना उचित न ठहराएँ।'],'काम बदलने पर प्रशिक्षण और अधिकार जाँचें।\nKYT में खतरे की पहचान से क्रियान्वित किए जा सकने वाले लक्ष्य तक जाएँ।'),
('जोखिम मूल्यांकन और उपायों का प्रभाव अलग सोचें','खतरे के स्रोत, संभावना और नुकसान की गंभीरता अलग करें।\nउपाय के बाद बचा जोखिम जाँचें।',[
('खतरा पहचानकर प्रभाव सोचें','जोखिम आकलन में खतरे के स्रोत पहचानते हैं और घटना की संभावना तथा नुकसान की गंभीरता आदि से प्राथमिकता सोचते हैं। काम की आवृत्ति समान हो तो भी गिरने और गर्म द्रव छिटकने के नुकसान अलग हैं। कार्यस्थल की तय मूल्यांकन विधि प्रयोग करें; पुस्तक से अपनी वैधानिक अंक प्रणाली न बनाएँ।\nनियर मिस ऐसी घटना है जिसमें चोट न लगी पर खतरा महसूस हुआ। हाइनरिख अनुपात को छोटी घटनाओं से सीखने के विचार की तरह लें; हर कार्यस्थल की दुर्घटना संभावना की गारंटी न मानें।'),
('उपाय लागू करना और प्रभाव अलग हैं','खतरा हटाने या उपकरण और कार्यविधि से घटाने पर विचार करें; आवश्यक प्रशिक्षण औरPPE भी मिलाएँ। केवल “सावधान रहें” कहने से उपाय पूरे नहीं होते। जिम्मेदार व्यक्ति के स्वीकृत उपाय लागू करें; बचे खतरे और रोकने की शर्तें साझा करें।\nबाद में समान शर्तों पर प्रभाव जाँचें। फिसलनरोधी चटाई का किनारा उठा हो तो ठोकर का नया खतरा बनता है। मूल खतरा घटा है और नया खतरा नहीं बढ़ा है, यह जाँचें।'),
('OSHMS में समीक्षा जारी रखें','OSHMS में सुरक्षा और स्वास्थ्य के लक्ष्य और योजना बनाकर लागू करते हैं, परिणाम आँकते और सुधारते हैं। केवल दस्तावेज बनाना या प्रशिक्षण देना प्रभाव की जाँच नहीं है। वास्तविक स्थिति और रिकॉर्ड मिलाएँ।\nदुर्घटना बिल्कुल नहीं हो सकती ऐसा न मानें। उपकरण खराबी, मानवीय गलती और आपदा की कल्पना करके अवशिष्ट जोखिम सँभालें। छोटी असामान्यता न छोड़ें; कारण जाँचने के लिए खतरनाक क्षेत्र में भी न जाएँ।'),
('समान उपाय में भी जाँच चाहिए','कंटेनर ले जाते समय फिसलन रोकने के लिए फर्श बदलने के बाद जिम्मेदार व्यक्ति बचे द्रव के स्थान और ट्रॉली की गति जाँचे। पहले और बाद की शर्तें रिकॉर्ड करें; फर्श की रसायन प्रतिरोधकता और सफाई विधि से अनुकूलता भी जाँचें। केवल स्थापना के दिन को पूर्णता न मानें।')],['चोट या स्वास्थ्य हानि पैदा कर सकने वाली वस्तु या स्थिति।','उपायों के बाद बचा जोखिम।','दुर्घटना न होने पर भी खतरा महसूस होने की घटना।','सुरक्षा और स्वास्थ्य की योजना, क्रियान्वयन, मूल्यांकन और सुधार की व्यवस्था।'],'शब्द4मिनट, खतरे के स्रोत और नुकसान8मिनट, उपाय और प्रभाव जाँच8मिनट, फर्श का उदाहरण7मिनट;3मिनट में अवशिष्ट जोखिम समझाएँ।',['उपाय या उपकरण बदलाव के लिए निर्धारित स्वीकृति लें।','असामान्यता दिखे तो खतरे के स्रोत के पास जाकर परीक्षण न करें।'],'उपाय करना और खतरा घटना अलग बातें हैं।\nबाद की स्थिति और बचे खतरे जाँचें।'),
('निषेध, चेतावनी और निकासी संकेतों को कार्रवाई से जोड़ें','संकेत के प्रकार और आवश्यक कार्रवाई अलग पहचानें।\nकेवल रसायन के चित्रचिह्न से संभालने की शर्तें तय न करें।',[
('निषेध और चेतावनी अलग पढ़ें','निषेध संकेत उस स्थान या स्थिति में मना व्यवहार बताते हैं। प्रवेश निषेध, आग सख्त मना, न छुएँ और पीने योग्य नहीं जैसे संकेतों में प्रतिबंधित क्रिया अलग पहचानें। केवल लाल रंग से अनुमान न करें; आकार और शब्द साथ पढ़ें।\nचेतावनी संकेत विद्युत झटका, फिसलन, ऊँच-नीच, सिर के ऊपर खतरा और ऊँचाई से गिरने आदि की सूचना देते हैं। संकेत होने से खतरा खत्म नहीं होता। चलने या काम से पहले निर्धारित रास्ता और सुरक्षा विधि जाँचें।'),
('रासायनिक संकेतSDS के साथ पढ़ें','ज्वाला, संक्षारण, स्वास्थ्य हानि, पर्यावरण हानि और विस्मयादिबोधक चिह्न खतरे पहचानने के संकेत हैं। समान चित्रचिह्न होने परPPE और भंडारण की शर्तें पूरी तरह समान हों, जरूरी नहीं। उत्पाद नाम, सावधानियाँ,SDS और कार्यस्थल की विधि मिलाएँ।\nकेवल एक चित्रचिह्न दिखने से अन्य खतरा नहीं है ऐसा न मानें। लेबल अधूरा, अस्पष्ट या कंटेनर से असंगत हो तो उपयोग रोककर पुष्टि करें।'),
('उपकरण का स्थान और निकासी गंतव्य जाँचें','अग्निशामक औरAED के संकेत उनका स्थान बताते हैं। निकासी स्थल, निकासी भवन और सुनामी आश्रय के उद्देश्य अलग हो सकते हैं। कार्यस्थल की निकासी योजना में संभावित आपदा के अनुकूल रास्ता और एकत्र स्थान जाँचें।\nसंकेत पहचानने का अर्थ हर परिस्थिति में स्वयंAED या अग्निशामक चलाना नहीं। आपातकाल में सूचना और निकासी समेत कार्यविधि और जिम्मेदार व्यक्ति के निर्देश मानें; खतरनाक स्थान में वापस न जाएँ।'),
('अस्पष्ट संकेत अनसुलझे न छोड़ें','रसायन भंडार के प्रवेश पर आग सख्त मना और दूसरे रास्ते पर प्रवेश निषेध है। दोनों को केवल “सावधानी” न कहें; मना क्रिया और निषिद्ध क्षेत्र जाँचें। निकासी दिशा अस्पष्ट हो तो सामान्य समय में पूछें; वास्तविक अलार्म के समय पहली बार खोजने से बचें।')],['मना व्यवहार बताने वाला संकेत।','खतरनाक स्थिति की मौजूदगी बताने वाला संकेत।','आकार या चित्र से सूचना देने वाला चिह्न।','सुरक्षित निकासी के लिए निर्धारित रास्ता।'],'शब्द4मिनट, निषेध और चेतावनी8मिनट, रासायनिक संकेत8मिनट, निकासी योजना की जाँच सूची7मिनट;3मिनट में अपठनीय संकेत पर कार्रवाई लिखें।',['लेबल का अनुमान लगाने के लिए अज्ञात रसायन का कंटेनर न खोलें।','संकेत जाँचने के लिए प्रवेश निषेध क्षेत्र में न जाएँ।'],'संकेत का अर्थ ठोस कार्रवाई से जोड़ें।\nरसायन के लिएSDS और निकासी के लिए कार्यस्थल की योजना भी जाँचें।')]
